const size_t kFoldRepCount = 1199;

uint16_t canonNu(uint16_t c) {
    size_t lo = 0, hi = kCanonNuCount;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (kCanonNu[mid].from < c) lo = mid + 1;
        else hi = mid;
    }
    if (lo < kCanonNuCount && kCanonNu[lo].from == c) return kCanonNu[lo].to;
    return c;
}

uint32_t foldRep(uint32_t cp) {
    size_t lo = 0, hi = kFoldRepCount;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (kFoldRep[mid].from < cp) lo = mid + 1;
        else hi = mid;
    }
    if (lo < kFoldRepCount && kFoldRep[lo].from == cp) return kFoldRep[lo].to;
    return cp;
}

